insert into public.srd_equipment (id,nome,tipo,preco,custo_po,descricao,srd_source_url,categoria,detalhes) values
('srd35_magic_regeneration','Regeneration','magic_item',90000,90000,'This white gold ring continually allows a living wearer to heal 1 point of damage per level every hour rather than every day. (This ability cannot be aided by the Heal skill.) Nonlethal damage heals at a rate of 1 point of damage per level every 5 minutes. If the wearer loses a limb, an organ, or any other body part while wearing this ring, the ring regenerates it as the spell. In either case, only damage taken while wearing the ring is regenerated.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"90,000 gp","roll_result":"— — 87–88","raw_table_row":["—","—","87–88","Regeneration","90,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_three_wishes','Three wishes','magic_item',97950,97950,'This ring is set with three rubies. Each ruby stores a wish spell, activated by the ring. When a wish is used, that ruby disappears. For a randomly generated ring, roll 1d3 to determine the remaining number of rubies. When all the wishes are used, the ring becomes a nonmagical item.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"97,950 gp","roll_result":"— — 89","raw_table_row":["—","—","89","Three wishes","97,950 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_spell_turning','Spell turning','magic_item',98280,98280,'Up to three times per day on command, this simple platinum band automatically reflects the next nine levels of spells cast at the wearer, exactly as if spell turning had been cast upon the wearer.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"98,280 gp","roll_result":"— — 90–92","raw_table_row":["—","—","90–92","Spell turning","98,280 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_wizardry_iv','Wizardry (IV)','magic_item',100000,100000,'Listed in Table: Rings; market price 100,000 gp. The specific item entry is not individually written out in this SRD table.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"100,000 gp","roll_result":"— — 93–94","raw_table_row":["—","—","93–94","Wizardry (IV)","100,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":false}'::jsonb),
('srd35_magic_djinni_calling','Djinni calling','magic_item',125000,125000,'One of the many rings of fable, this “genie” ring is most useful indeed. It serves as a special gate by means of which a specific djinni can be called from the Elemental Plane of Air. When the ring is rubbed (a standard action), the call goes out, and the djinni appears on the next round. The djinni faithfully obeys and serves the wearer of the ring, but never for more than 1 hour per day. If the djinni of the ring is ever killed, the ring becomes nonmagical and worthless.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"125,000 gp","roll_result":"— — 95","raw_table_row":["—","—","95","Djinni calling","125,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
