('srd35_magic_spell_storing_major','Spell storing, major','magic_item',200000,200000,'As the minor ring of spell storing, except it holds up to ten levels of spells.','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iii-potions-rings-and-rods.md','rings','{"source_file":"magic-items-iii-potions-rings-and-rods.md","source_table":"Table: Rings","market_price":"200,000 gp","roll_result":"— — 100","raw_table_row":["—","—","100","Spell storing, major","200,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
