('srd35_magic_charming','Charming','magic_item',16500,16500,'Made of twisting wood ornately shaped and carved, this staff allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"16,500 gp","roll_result":"01–15 01–03","raw_table_row":["01–15","01–03","Charming","16,500 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
