('srd35_magic_illumination','Illumination','magic_item',48250,48250,'This staff is usually sheathed in silver and decorated with sunbursts. It allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"48,250 gp","roll_result":"76–90 20–24","raw_table_row":["76–90","20–24","Illumination","48,250 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_frost','Frost','magic_item',56250,56250,'Tipped on either end with a glistening diamond, this rune-covered staff allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"56,250 gp","roll_result":"91–95 25–31","raw_table_row":["91–95","25–31","Frost","56,250 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_defense','Defense','magic_item',58250,58250,'The staff of defense is a simple-looking staff that throbs with power when held defensively. It allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"58,250 gp","roll_result":"96–100 32–38","raw_table_row":["96–100","32–38","Defense","58,250 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
