('srd35_magic_enchantment','Enchantment','magic_item',65000,65000,'Often made from applewood and topped with a clear crystal, this staff allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"65,000 gp","roll_result":"— 49–53","raw_table_row":["—","49–53","Enchantment","65,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_evocation','Evocation','magic_item',65000,65000,'Usually very smooth and carved from hickory, willow, or yew, this staff allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"65,000 gp","roll_result":"— 54–58","raw_table_row":["—","54–58","Evocation","65,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_illusion','Illusion','magic_item',65000,65000,'This staff is made from ebony or other dark wood and carved into an intricately twisted, fluted, or spiral shape. It allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"65,000 gp","roll_result":"— 59–63","raw_table_row":["—","59–63","Illusion","65,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
('srd35_magic_necromancy','Necromancy','magic_item',65000,65000,'This staff is made from ebony or other dark wood and carved with the images of bones and skulls. It allows use of the following spells:','https://github.com/olimot/srd-v3.5-md/blob/main/magic-items/magic-items-iv-scrolls-staffs-and-wands.md','staffs','{"source_file":"magic-items-iv-scrolls-staffs-and-wands.md","source_table":"Table: Staffs","market_price":"65,000 gp","roll_result":"— 64–68","raw_table_row":["—","64–68","Necromancy","65,000 gp"],"source_dataset":"olimot/srd-v3.5-md","license":"Open Game Content / OGL 1.0a","has_full_item_description":true}'::jsonb),
